import pandas as pd
from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))
def tr_age(a):
    if(a < 18):
        return 'Under 18'
    elif(a <= 25):
        return '18-25'
    else:
        return 'Above 25'

def transform_df(df):
    # Your code here
    colors = ['blue','brown','green']
    df['height'] = df['height'].round(1)
    df['datetime'] = pd.to_datetime(df['dates'])
    df['month'] = df['datetime'].dt.month
    df['day'] = df['datetime'].dt.day
    for color in colors:
        df[color] = (df['color'] == color).astype(int)
    df['age'] = df['age'].apply(tr_age)
    return df[['age','blue','brown','green','month','day','height']]

print(transform_df(df))
