from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    # Map the age column in "Under 18" or "18-25" or "25+"
    df['age'] = df['age'].apply(lambda x: "Under 18" if x < 18 else "18-25" if x < 25 else "25+")

    # Map the color column into three separate columns, "brown" "blue" and "green". The new columns
    # should have a 1 or 0 based on the contents of the original "color" column
    df['blue'] = df['color'].apply(lambda x: 1 if x == 'blue' else 0)
    df['brown'] = df['color'].apply(lambda x: 1 if x == 'green' else 0)
    df['green'] = df['color'].apply(lambda x: 1 if x == 'green' else 0)

    # Delete the color column
    df = df.drop('color', axis=1)

    # Round the height column to the nearest integer
    df['height'] = df['height'].apply(lambda x: round(x))

    # Take the dates column and replace it with a "day" column that only contains the day
    # from the date
    df['dates'] = pd.to_datetime(df['dates'])
    df['month'] = df['dates'].dt.month
    df['day'] = df['dates'].dt.day
    df = df.drop('dates', axis=1)

    # Return the transformed DataFrame
    return df

print(transform_df(df))
