import pandas as pd
from io import StringIO

# Original dataset
data = '''
col1,col2,col3,col4,col5
6,4,0.5671297731744318,10,4
1,6,2.726562945801132,9,6
4,3,4.776651173213499,10,1
4,5,8.121687287754932,5,3
8,8,4.799771723750573,4,4
10,7,3.9278479610082973,1,9
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):

    # Calculate the sum for col1 through col4
    total = df[["col1", "col2", "col3", "col4"]].sum(axis=1)

    # Calculate the mean for col2 through col5
    mean = df[["col2", "col3", "col4", "col5"]].mean(axis=1)

    # Add columns "Total" and "Mean" to the DataFrame
    df["Total"] = total
    df["Mean"] = mean

    return df

print(transform_df(df))
