    sample1 = numpy.array(sample1)
    sample2 = numpy.array(sample2)

    mean1 = numpy.mean(sample1)
    mean2 = numpy.mean(sample2)

    var1 = numpy.var(sample1, ddof=1)
    var2 = numpy.var(sample2, ddof=1)

    n1 = len(sample1) 
    n2 = len(sample2)

    array1 = numpy.sum((sample1 - mean1) * (sample2 - mean2))
    array2 = numpy.sum((sample1 - mean1)**2)
    array3 = numpy.sum((sample2 - mean2)**2)

    sp = numpy.sqrt((array2+array3)/(n1+n2-2))

    t_test = (mean1-mean2)/(sp*numpy.sqrt(1/n1+1/n2))

    return t_test
