    n1 = len(sample1) 
    n2 = len(sample2)

    array2 = numpy.sum((sample1 - mean1)**2)/n1
    array3 = numpy.sum((sample2 - mean2)**2)/n2

    t_test = abs((mean1-mean2)/(numpy.sqrt(var1/n1 + var2/n2)))

    return t_test
