def transform_age(age):
    if(age < 18):
        return "Under 18"
    if(age > 18 and age < 25):
        return "18-25"

def transform_df(df):
    # Your code here
    df["height"] = df["height"].apply(lambda x: round(x))
    df["age"] = df["age"].apply(lambda x: transform_age(x))
    df["brown"] = df["color"].apply(lambda x: 1 if x=="brown" else 0)
    df["blue"] = df["color"].apply(lambda x: 1 if x=="blue" else 0)
    df["green"] = df["color"].apply(lambda x: 1 if x=="green" else 0)
    df["month"] = df["dates"].apply(lambda x: int(x[5:7]))
    df["day"] = df["dates"].apply(lambda x: int(x[8:10]))
    df = df.drop(columns=["color","dates"])
    print(df)
print(transform_df(df))

