    def __init__(self, vectors, k):
        self.vectors = vectors
        self.k = k
    def set_k(self, k):
        if k>=1 and k<=len(self.vectors):
            self.k=k
    def add_vectors(self, vectors):
        self.vectors = np.array(self.vectors.tolist()
    def distance(self, q):
        dists = []
        for vec in self.vectors:
            dists.append(np.sum((vec-q)**2))
        return dists
    def get_top_k_similar_vectors(self, q):
        dists = self.distance(q)
        vecs = [(self.vectors[i], dists[i]) for i in range(len(self.vectors))]
        vecs.sort(lambda x: x[1])
        return np.array([vecs[i] for i in range(self.k)])
    def similarity_matrix(self, vecs):
        all_dists = []
