class LoginAuthenticator:
    def __init__(self):
        # DO NOT CHANGE
        self.user_credentials = {}  # dictionary for username: hashed_password

    def _hash_password(self, password):
        # WRITE CODE HERE

        return hash(password) 

    def add_user(self, username, password):
        # WRITE CODE HERE
        # check user in sys
        if username in self.user_credentials: 
            return False
        else:
            hashed_pass = self._hash_password(password)
            self.user_credentials[username] = hashed_pass
            return True 
        return False 

    def authenticate_user(self, username, password):
        # DO NOT CHANGE
        #Checks if the given username and password are valid
        if username not in self.user_credentials:
            return False
        return self.user_credentials[username] == self._hash_password(password)

    def remove_user(self, username):
        # WRITE CODE HERE
        if username in self.user_credentials:
            del self.user_credentials[username]
            return True 
        else:
            return False

    def change_password(self, username, old_password, new_password):
        # WRITE CODE HERE

        if authenticate_user(username, old_password):
            self.user_credentials[username] = self._hash_password(new_password)
            return True

        return False
