def order_by_points(nums):
    """

    > order_by_points([1, 11, -1, -11, -12])
    [-1, -11, 1, -12, 11]
    """
    nums_with_counts = [(i, my_sum(i)) for i in nums]
    sorted_list = sorted(nums_with_counts, key=lambda x: x[1])
    result = list(map(lambda x: x[0], sorted_list))
    return result

