    v1 /= (n1 - 2)
    s2 = 0
    for x in sample2:
        s2 += (x - mean2)**2
    v2 /= (n2 - 2)

    t_test = abs((mean1-mean2)/sqrt((variance1/n1)+(variance2/n2)))

    return t_test
