","66":"class LoginAuthenticator:
    def __init__(self):
        # DO NOT CHANGE
        self.user_credentials = {}  # dictionary for username: hashed_password

    def _hash_password(self, password):
        # WRITE CODE HERE
        # Encode the password to bytes
        password_bytes = password.encode()

        # Create a SHA-256 hash object
        hash_object = hashlib.sha256()

        # Update the hash object with the password bytes
        hash_object.update(password_bytes)

        # Get the hexadecimal representation of the hashed password
        hashed_password = hash_object.hexdigest()

        # Return the hashed password as a string
        return hashed_password

    def add_user(self, username, password):
        # WRITE CODE HERE
        # if user in system
        if username in self.user_credentials:
            return False
        else:
            # hash the password
            hashed_pw = self._hash_password(password)
            # store user
            self.user_credentials[username] = hashed_pw
            return True


    def authenticate_user(self, username, password):
        # DO NOT CHANGE
        #Checks if the given username and password are valid
        if username not in self.user_credentials:
            return False
        return self.user_credentials[username] == self._hash_password(password)

    def remove_user(self, username):
        # WRITE CODE HERE
        # if user in system
        if username in self.user_credentials:
            del self.user_credentials[username] 
            return True
        return False


