    # empty case
    if len(numbers) == 0:
        return (0,1)

    num_sum = 0
    num_product = 0
    for i in range(len(numbers)):
        num_sum += numbers[i]
        if i == 0:
            num_product += 1*numbers[i]
        else:
            num_product += num_product*numbers[i]

    return (num_sum, num_product)

