20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    # drop colors
    drop_cols = ['color', 'dates']
    df = df.drop(drop_cols, axis=1)

    # add cols
    new_cols = {'day': [6, 5, 10, 7, 4],
                'month': [3, 3, 3, 3, 1],
                'green': [0, 0, 1, 0, 3],
                'brown': [1, 1, 0, 0, 0],
                'blue': ['Under 18', 'Under 18', 'Under 18', 'Under 18','18-25'],
                }

    for col_name, col_vals in new_cols.items():
        df.insert(1, col_name, col_vals)

    df['height'] = int(df['height'])
    return df

print(transform_df(df))
