def is_product_of_3_primes(num):
    count = 0

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0 and is_prime(i):
            count += 1
            if count > 3:
                break

    return count == 3


