def schedule_events(events):
    score = 0
    elapsed = 0
    sortedEvents = sorted(events, key=lambda x: x[1])
    for e in sortedEvents:
        if e[0] >= elapsed:
            score += e[2]
            elapsed = e[1]
    return score

