import math

class Retriever:

    def __init__(self, vectors, k):
        self.vectors = vectors
        self.k = k

    def set_k(self, new_k):
        if (1 <= new_k <= len(self.vectors)):
            self.k = new_k

    def add_vectors(self, new_vectors):
        self.vectors = np.concatenate((self.vectors, new_vectors))

    def distance(self, query_vector):
        distances = []

        q_x, q_y = query_vector[0], query_vector[1]

        for vector in self.vectors:
            x, y = vector[0], vector[1]
            dist = math.sqrt(pow(q_x-x, 2) + pow(q_y-y, 2))

            distances.append(dist)

        return np.array(distances)

    def get_top_k_similar_vectors(self, query_vector):
        distances = self.distance(query_vector)

        distances_list = distances.tolist()
        vector_list = self.vectors.tolist()

        sort_arr = [(distances_list[i], vector_list[i]) for i in range(len(vector_list))]
        sort_arr.sort()

        return np.array([dist for dist, _ in sort_arr[:self.k]])

    def get_similarity_matrix(self, query_vectors):
        arr = []

        for query_vector in query_vectors:
            arr.append(self.distance(query_vector))

        return np.array(arr)

