class Tokenizer:
    def __init__(self, max_vocab_size=200):
        self.max_vocab_size = max_vocab_size
        self.word_to_id = {}
        self.id_to_word = {}

    def tokenize(self, text):
        # do not change
        # Split text into words by spaces
        return text.lower().split()

    def build_vocabulary(self, corpus):
        '''
        corpus: a list of strings (string denotes a sentence composed of words seperated by spaces)
        '''
        word_freq = {}
        for sentence in corpus:
            words = self.tokenize(sentence)
            for word in words:
                if word in word_freq:
                    word_freq[word] += 1
                else:
                    word_freq[word] = 1

        # Sort the words by frequency (high to low)
        sorted_words = sorted(word_freq.items(), key=lambda item: item[1], reverse=True)

        # Take the most frequent `max_vocab_size` words
        most_frequent_words = sorted_words[:self.max_vocab_size]

        # Create word <-> id mappings
        self.word_to_id = {word: idx for idx, (word, _) in enumerate(most_frequent_words)}
        self.id_to_word = {idx: word for word, idx in self.word_to_id.items()}
        return 

    def get_word_id(self, word):
        # do not change
        # Retrieve the ID of a word, return None if the word is not in the vocabulary
        return self.word_to_id.get(word)

    def get_word_by_id(self, word_id):
        # do not change
        # Retrieve a word by its ID, return None if the ID is not in the vocabulary
        return self.id_to_word.get(word_id)
