def simplified_t_test(sample1, sample2):
    '''
    :param sample1: List or array of sample data (sample 1)
    :param sample2: List or array of sample data (sample 2)
    :return: simplified t-test statistic
    '''
    t_test = 0

    sum1=sum(sample1)
    count1=len(sample1)
    mean1= sum1/count1

    sum2=sum(sample2)
    count2=len(sample2)
    mean2=sum2/count2

    variance1=sum((x-mean1)^2/(int(count1) - 2))
    variance2=sum((x-mean2)^2/(int(count2) - 2))



    t_test=abs((mean1-mean2)/sqrt((variance1/count1)+(variance2/count2)))
    return t_test
