import hashlib

class LoginAuthenticator:
    def __init__(self):
        # DO NOT CHANGE
        self.user_credentials = {
        }  # dictionary for username: hashed_password

    def _hash_password(self, password):
        # WRITE CODE HERE
        password_bytes = password.encode('utf-8')
        sha256_hash = hashlib.sha256()
        sha256_hash.update(password_bytes)
        return sha256_hash.hexdigest()

    def add_user(self, username, password):
        # WRITE CODE HERE
        if username in self.user_credentials.keys():
            return False
        self.user_credentials[username] = self._hash_password(password)
        return True

    def authenticate_user(self, username, password):
        # DO NOT CHANGE
        #Checks if the given username and password are valid
        if username not in self.user_credentials:
            return False
        return self.user_credentials[username] == self._hash_password(password)

    def remove_user(self, username):
        # WRITE CODE HERE
        if username in self.user_credentials.keys() == False:
            return False
        del self.user_credentials[username]
        return True

    def change_password(self, username, old_password, new_password):
        # WRITE CODE HERE
        if self.authenticate_user(username, old_password) == False:
            return False
        self.user_credentials[username] = self._hash_password(new_password)
        return True
