'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    # Creating a category column for age
    df["age_category"] = pd.cut(df["age"], bins=[0, 18, 25], labels=["Under 18", "18-25"], right=False)

    # Extracting month and day from dates
    df["dates"] = pd.to_datetime(df["dates"])
    df["month"] = df["dates"].dt.month_name()
    df["day"] = df["dates"].dt.day

    # Pivot the DataFrame to get one-hot encoding for colors
    df_pivot = df.pivot_table(index=["age_category", "month", "day"], columns="color", values="age", aggfunc="size").reset_index()
    df_pivot = df_pivot.fillna(0).rename_axis(None, axis=1)

    # Merging the pivot with the original DataFrame to bring back 'height' column
    df_height = df.groupby(["age_category", "month", "day"])["height"].mean().reset_index()
    df_result = pd.merge(df_pivot, df_height, how="left", on=["age_category", "month", "day"])

    # Reordering columns
    df_result = df_result[["age_category", "blue", "brown", "green", "month", "day", "height"]]

    return df_result

print(transform_df(df))

