    """Hash a string using the DJB2 algorithm."""
    hash_value = 5381
    for char in string:
        # ord(char) gets the ASCII value of the character
        hash_value = ((hash_value << 5) + hash_value) + ord(char)  # hash_value * 33 + ord(char)
    return hash_value & 0xFFFFFFFF  # Return as a 32-bit unsigned integer


