import pandas as pd
from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def categorize_age(age):
    if age < 18:
        return "Under 18"
    else:
        return "18-25"

def transform_df(df):
    df['dates'] = pd.to_datetime(df['dates'])
    df['age'] = df['age'].apply(categorize_age)
    df['blue'] = df['color'].apply(lambda x: x == 'blue')
    df['brown'] = df['color'].apply(lambda x: x == 'brown')
    df['green'] = df['color'].apply(lambda x: x == 'green')
    df['month'] = dt['dates'].month
    df['day'] = dt['dates'].dt.day
    df['height'] = df['height'].apply(lambda x: round(x))
    df.drop('color', axis=1, inplace=True)
    df.drop('dates', axis=1, inplace=True)
    df = df.reindex(columns=['age', 'blue', 'brown', 'green', 'month', 'day', 'height'])
    return df

print(transform_df(df))
