import math

def mean(data):
    return sum(data) / len(data)

def variance(data, ddof=1):
    data_mean = mean(data)
    return sum((x - data_mean) ** 2 for x in data) / (len(data) - ddof)

def t_test(sample1, sample2):
    mean1 = mean(sample1)
    mean2 = mean(sample2)
    var1 = variance(sample1)
    var2 = variance(sample2)

    n1 = len(sample1)
    n2 = len(sample2)

    # Calculate the t statistic
    t_statistic = (mean1 - mean2) / math.sqrt((var1 / n1) + (var2 / n2))

    # Degrees of freedom
    dof = (((var1 / n1) + (var2 / n2)) ** 2) / (((var1 / n1) ** 2) / (n1 - 1) + ((var2 / n2) ** 2) / (n2 - 1))

    return t_statistic, dof

# Example usage
sample1 = [2.3, 3.1, 2.2, 3.8, 2.6]
sample2 = [3.5, 2.9, 4.0, 3.7, 4.2]

t_stat, dof = t_test(sample1, sample2)
print(f"T-statistic: {t_stat}, Degrees of freedom: {dof}")

