4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    df['age'] = pd.cut(df['age'], bins=[0, 18, 26], labels=['Under 18', '18-25'])
    df['height'] = df['height'].astype(int)
    df['day'] = pd.to_datetime(df['dates'], format='%Y-%m-%d').dt.day
    df['month'] = pd.to_datetime(df['dates'], format='%Y-%m-%d').dt.month
    df_pivoted = pd.get_dummies(df, columns=['color'])
    df_pivoted.rename(columns={'color_blue': 'blue', 'color_brown': 'brown', 'color_green': 'green'}, inplace=True)
    df_pivoted = df_pivoted[['age','blue','brown','green','month','day', 'height']]
    print(df_pivoted)

print(transform_df(df))
