import pandas as pd
from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    # Your code here
    new_df = {}
    def age_lambda(a):
        if int(a) < 18:
            return "Under 18"
        else:
            return "18-25"

    new_df['age'] = df['age'].apply(age_lambda)

    color_dummies = pd.get_dummies(df['color'])
    new_df['blue'] = color_dummies['blue']
    new_df['brown'] = color_dummies['brown']
    new_df['green'] = color_dummies['green']

    # month and day
    new_df['month'] = df['dates'].apply(lambda dts: int(''.join(list(str(dts))[5:7])))
    new_df['day'] = df['dates'].apply(lambda dts: int(''.join(list(str(dts))[0:4])))

    new_df['height'] = df['height'].apply(lambda h: int(h))

    return pd.DataFrame(new_df)

print(transform_df(df))
