        if k >= 1 and k < len(self.vectors):
            self.k = k

    def add_vectors(self, vectors):

        self.vectors = np.concatenate((self.vectors, vectors), axis=0)

    def distance(self, vector):

        distance = np.sqrt(np.sum(np.square(self.vectors - vector), axis=1))
        return distance

