    return date.month, date.day

def parse_age(date):
    return 'Under 18' if (pd.datetime(date) - pd.datetime('2019-03-02')).days > 0 else '18-25'

def transform_df(df):
    new_df = pd.DataFrame(columns=['age', 'blue', 'brown', 'green', 'month', 'day', 'height']
    for i, row in df.iterrows():
        year, month, day = parse_date(row['dates'])
        new_row = {'age': parse_age(month, day), 'blue':0, 'brown':0, 'green':0, 'month': month, 'day': day, 'height': round(row['height'])}
        new_df.append(new_row, ignore_index=True)
    return new_df

print(transform_df(df))
