    if not l or len(l) < 3: return False
    if len(l) == 3:
        return sum(l) == 0
    l = sorted(l)
    for i in range(len(l)-2):
        j, k = i + 1, len(l) - 1
        while j < k:
            curr_sum = l[i] + l[j] + l[k]
            if curr_sum == 0:
                return True
            elif curr_sum > 0:
                k -= 1
            else:
                j += 1
    return False
