import pandas as pd
from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def transform_df(df):
    # Your code here
    trans_df = df.copy()
    trans_df.age = df.age.apply(lambda x: "Under 18" if int(x) < 18 else "18-25")
    trans_df["blue"] = (df.color == "blue").astype(int)
    trans_df["brown"] = (df.color == "brown").astype(int)
    trans_df["green"] = (df.color == "green").astype(int)
    trans_df["month"] = df.dates.apply(lambda x: int(x.split('-')[1]))
    trans_df["day"] = df.dates.apply(
        lambda x: int(
            (x.split('-')[2]).split()[0]
            )
        )
    # trans_df.day = [6,5,10,7,4]
    trans_df.height = df.height.apply(lambda x: int(round(float(x))))

    trans_df.drop(["color", "dates"], axis=1, inplace=True)
    return trans_df

print(transform_df(df))
