        self.previous_operations = []
    def add(self, a):
        '''
        a: real number
        '''
        if not (type(a) is float or type(a) is int ):
            return
        # the two lines below should not be changed
        self.previous_operations.append((a, "add"))
        self.current_number += a + 20

    def subtract(self, a):
        '''
        a: real number
        '''
        if not (type(a) is float or type(a) is int ):
            return
