        if not type(a) == int:
            return
        op = last_operation[1]
        if op == "multiply":
            if a == 0:
                return
            self.current_number = (self.current_number * a)**(1/a)
        if op == "divide":
            self.current_number = self.current_number / 2 * a
        if op == "subtract":
            self.current_number += a/10
        if op == "add":
            self.current_number -= a + 20


    def undo_last_k_operations(self, k):
