def transform_df(df):
    # Your code here
    new_df = pd.DataFrame(index=df.index)
    new_df['age'] = df['age'].apply(lambda x: 'Under 18' if x < 18 else '18-25')
    df_dummies = pd.get_dummies(df['color'])
    new_df = pd.concat([new_df,df_dummies],axis=1)
    df['dates'] = pd.to_datetime(df['dates'])
    new_df['month'] = df['dates'].dt.month
    new_df['day'] = df['dates'].dt.day
    new_df['height'] = df['height'].round().astype(int)

    return new_df

