import pandas as pd
from io import StringIO

# Original dataset
data = '''
age,color,dates,height
1,blue,2019-03-06,2.72656
4,blue,2019-03-05,4.77665
4,green,2019-03-10,8.12169
10,brown,2019-03-07,4.79977
20,green,2019-03-01,3.92785
'''

# Read the dataset into a DataFrame
df = pd.read_csv(StringIO(data))

def set_age(age):
    if(age < 18):
        return 'Under 18'
    else:
        return '18-25'

def blue(col):
    if(col == 'blue'):
        return 1
    else:
        return 0

def brown(col):
    if(col == 'brown'):
        return 1
    else:
        return 0

def green(col):
    if(col == 'green'):
        return 1
    else:
        return 0

def transform_df(df):
    age = df['age']
    age_col = age.apply(set_age)
    df['age'] = age_col

    blue_col = df['color'].apply(blue)
    df['blue'] = blue_col

    green_col = df['color'].apply(green)
    df['green'] = green_col

    brown_col = df['color'].apply(brown)
    df['brown'] = brown_col

    del df['color']



    return df

print(transform_df(df))

