def sum_of_digits(n):
    """Helper function to calculate the sum of digits of an integer."""
    return sum(int(digit) for digit in str(n))

def sort_by_digit_sum(lst):
    """Function to sort a list of integers based on the sum of their digits."""
    return sorted(lst, key=sum_of_digits)

# Example usage:
numbers = [56, 23, 87, 12, 39, 40]
sorted_numbers = sort_by_digit_sum(numbers)
