def sum_of_digits(n):
    """Helper function to calculate the sum of digits of a number, accounting for the sign."""
    sign = -1 if n < 0 else 1
    return sign * sum(int(digit) for digit in str(abs(n)))

def sort_by_digit_sum(lst):
    """
    Function to sort a list of integers in ascending order based on the sum
    of their digits. Considers the sign of the numbers in calculating the digit sum.
    """
    return sorted(lst, key=sum_of_digits)

