class Retriever:
    def __init__(self, vectors: np.ndarray, k: int):
        self.vectors = vectors
        self.k = k
    def set_k(self, k):
        if new_k <= 0 or n > len(self.vectors):
            raise ValueError(f"k must be between 1 and {len(self.vectors)}")
        self.k = new_k
    def distance(self, vec1: np.ndarray, vec2: np.ndarray) -> float:
        return np.linalg.norm(vec1 - vec2)
    def get_top_k_similar(self, query_vector: np.ndarray) -> np.ndarray:
        distances = np.array([self.euclidean_distance(query_vector, vec) for vec in self.vectors])
        top_k_indices = np.argsort(distances)[:self.k]  # Get indices of top k smallest distances
        return self.vectors[top_k_indices]
    def create_similarity_matrix(self) -> np.ndarray:
        num_vectors = self.vectors.shape[0]
        similarity_matrix = np.zeros((num_vectors, num_vectors))

        for i in range(num_vectors):
            for j in range(i, num_vectors):
                distance = self.euclidean_distance(self.vectors[i], self.vectors[j])
                similarity_matrix[i, j] = distance
                similarity_matrix[j, i] = distance  # The matrix is symmetric

        return similarity_matrix

