def is_multiply_prime(a):
    if a < 2: 
        return False

    def is_prime(n): 
        if n <= 1: 
            return False 
        if n <= 3: 
            return True 
        if n % 2 == 0 or n % 3 == 0: 
            return False 
        i = 5
        while i * i <= n: 
            if n % i == 0 or n % (i + 2) == 0: 
                return False 
            i += 6
        return True 

    def prime_factors(num): 
        factors = []
        # Check for number of 2s dividing num
        while num % 2 == 0:
            if 2 not in factors:
                factors.append(2)
            num //= 2
        # num must be odd at this point so we can skip even numbers
        for i in range(3, int(num**0.5)+1, 2):
            while num % i == 0:
                if i not in factors:
                    factors.append(i)
                num //= i
        if num > 2:
            factors.append(num)
        return factors

    factors = prime_factors(a) 
    return len(factors) == 3 and all(is_prime(factor) for factor in factors)

# Example usage:
print(is_multiply_prime(30))  # True (2 * 3 * 5)
print(is_multiply_prime(60))  # False (2 * 2 * 3 * 5)
