def prime_factors(n):
    factors = set()  # Use a set to avoid duplicate factors
    divisor = 2

    while n > 1:
        while n % divisor == 0:
            factors.add(divisor)
            n //= divisor
        divisor += 1

    return factors

def main():
    try:
        number = int(input("Enter a number to factorize: "))

        if number <= 1:
            print("Please enter a number greater than 1.")
        else:
            result = prime_factors(number)
            print(f"The unique prime factors of {number} are: {sorted(result)}")

    except ValueError:
        print("Please enter a valid integer.")

if __name__ == "__main__":
    main()

