def sieve_of_eratosthenes(n):
    if n < 2:
        return []

    # Initialize a list to track primes
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False  # We know 0 and 1 are not prime numbers

    p = 2
    while p * p <= n:
        if is_prime[p]:
            # Mark all multiples of p as False, starting from p^2
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    # Collecting all prime numbers
    primes = [p for p, prime in enumerate(is_prime) if prime]
    return primes

def main():
    try:
        number = int(input("Enter a number to find all primes till that number: "))

        if number < 2:
            print("There are no prime numbers less than 2.")
        else:
            result = sieve_of_eratosthenes(number)
            print(f"Prime numbers up to {number} are: {result}")

    except ValueError:
        print("Please enter a valid integer.")

if __name__ == "__main__":
    main()


