import math
# function signature
def simplified_t_test(sample1, sample2):
    '''
    :param sample1: List or array of sample data (sample 1)
    :param sample2: List or array of sample data (sample 2)
    :return: simplified t-test statistic
    '''

    t_test = 0
    n1 = len(sample1)
    n2 = len(sample2)
    mean1 = sum(sample1) / n1
    mean2 = sum(sample2) / n2
    var1 = 0
    for number in sample1:
        var1 += ((number - mean1)**2)/(n1 -2)
    var2 = 0
    for number in sample2:
        var2 += ((number - mean2)**2)/(n2 -2)

    t_test = abs((mean1 - mean2) / math.sqrt((var1 /n1) + (var2/n2)))

    # write your code here
    return t_test
