class Retriever:
    def __init__(self, vectors, k):
        super().__init__()
        self.vectors=vectors
        self.k = k

    def set_k(self, k):
        if k > 0 and k <= self.vectors.shape[0]:
            self.k = k

    def add_vectors(self, new_vectors):
        self.vectors = np.concatenate((self.vectors, new_vectors), 0)

    def distance(self, query_vector):
