class Retriever:
    def __init__(self, vectors, k):
        super().__init__()
        self.vectors=vectors
        self.k = k

    def set_k(self, k):
        if k > 0 and k <= self.vectors.shape[0]:
            self.k = k

    def add_vectors(self, new_vectors):
        self.vectors = np.concatenate((self.vectors, new_vectors), 0)

    def distance(self, query_vector):
        return ((self.vectors - query_vector)**2).sum(1)


    def get_top_k_similar_vectors(self, query_vector):
        d = self.distance(query_vector)
        idx = np.argsort(d)[:self.k]

        return self.vectors[idx]

    def get_similarity_matrix(self, query_vectors):
        if query_vectors.ndim == 1:
            query_vectors = query_vectors[None]

        sim = []
        for q in query_vectors:
            sim.append(self.distance(q))
        return np.stack(sim)

