    primes = []
    for i in range(2, 101):
        is_prime = True 
        for j in range(2, i):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)

    good_primes = [x for x in primes if a % x == 0]

    # naive - try all combos?
    combo_primes = []
    for x in good_primes:
        for y in good_primes:
            if x * y < a:
                combo_primes.append(x*y)

    for x in combo_primes:
        for y in good_primes:
            if x * y == a:
                return True

    return False


