class LoginAuthenticator:
    def __init__(self):
        # DO NOT CHANGE
        self.user_credentials = {}  # dictionary for username: hashed_password

    def _hash_password(self, password):
        # WRITE CODE HERE
        nums = [ord(c) for c in password]

        return (np.sum(nums) + 17) * (np.prod(nums) + 131)

    def add_user(self, username, password):
        # WRITE CODE HERE
        if username in self.user_credentials:
            return False
        hash = self._hash_password(password)
        self.user_credentials[username] = hash
        print(f'storing user={username}, password={password}, hash={hash}')
        return True

    def authenticate_user(self, username, password):
        # DO NOT CHANGE
        #Checks if the given username and password are valid
        if username not in self.user_credentials:
            return False
        hash = self._hash_password(password)
        print(f'checking user={username}, password={password}, hash={hash}')        
        return self.user_credentials[username] == hash

    def remove_user(self, username):
        # WRITE CODE HERE
        if username in self.user_credentials:
            del self.user_credentials[username]
            return True
        else:
            return False

    def change_password(self, username, old_password, new_password):
        # WRITE CODE HERE
        if username not in self.user_credentials:
            return 
        if not self.user_credentials[username] == self._hash_password(old_password):
            return False
        hash = self._hash_password(new_password)
        self.user_credentials[username] = hash
        return True


