class Retriever:
    def __init__(self, vecs, k):
        self.vectors = vecs
        self.k = k

    def set_k(self, k):
        if k >= 1 and k <= len(self.vectors):  
            self.k = k

    def add_vectors(self, new_vecs):
        self.vectors = np.concatenate((self.vectors, new_vecs), axis=0)

    def distance(self, qvec):
        dists = []
        for v in self.vectors:
            dists.append(np.sqrt(np.sum((qvec - v) ** 2)))
        return np.array(dists)

    def get_top_k_similar_vectors(self, qvec):
        dists = self.distance(qvec)
        dists = [(v, i) for i, v in enumerate(dists)]
        dists = sorted(dists)
        res = [self.vectors[i] for _, i in dists]
        return np.array(res[: self.k])

    def get_similarity_matrix(self, qvecs):
        res = []
        for qvec in qves:
            res.append(self.distance(qvec))
        return np.array(res)

