    l = sorted(l)
    n = len(l)
    for i in range(n-2):
        val = -l[i]
        j, k = i + 1, n - 1
        while j < k:
            sm = l[j] + l[k]
            if sm == val:
                return True
            elif sm > val:
                k -= 1
            else:
                j += 1
    return False

