# function signature
def simplified_t_test(sample1, sample2):
    '''
    :param sample1: List or array of sample data (sample 1)
    :param sample2: List or array of sample data (sample 2)
    :return: simplified t-test statistic
    '''

    mean1 = sum(sample1) / len(sample1);
    mean2 = sum(sample2) / len(sample2);
    diff1 = [(element - mean1) ** 2 for element in sample1]
    diff2 = [(element - mean2) ** 2 for element in sample2]
    variance1 = sum(diff1) / (len(sample1) - 2)
    variance2 = sum(diff2) / (len(sample2) - 2)
    t_test = abs((mean1 - mean2) / math.sqrt((variance1 / len(sample1)) + (variance2 / len(sample2))))
    return t_test
